-- SOCIAL-1F: Controlled Social NBA
-- Migration: 20260822180000_social_1f_controlled_nba.sql
--
-- Additive-only. No destructive changes to existing tables.
-- Do NOT apply to production without a review + change-control sign-off.
--
-- PURPOSE:
--   Persist Social NBA recommendations generated by SOCIAL-1F.
--   Provides:
--     - workspace-scoped RLS isolation
--     - idempotency constraint (no duplicate active recommendations for the
--       same workspace + identity + evidence window)
--     - append/audit-safe lifecycle (recommendations are never hard-deleted)
--     - policy decision + reasons preserved for downstream execution proof

-- ── Table ─────────────────────────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.social_nba_recommendations (
  id                      uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Workspace isolation (all queries MUST be scoped to this)
  workspace_id            text NOT NULL,

  -- Identity (from SOCIAL-1B)
  resolved_identity_key   text NOT NULL,
  canonical_person_id     uuid,  -- null for non-person identities
  identity_state          text NOT NULL
                            CHECK (identity_state IN (
                              'known_person', 'platform_actor',
                              'pseudonymous_visitor', 'anonymous_aggregate')),

  -- Social context
  provider                text NOT NULL,
  channel                 text NOT NULL,

  -- Intent (from SOCIAL-1D)
  intent_score            numeric(6,4) NOT NULL CHECK (intent_score >= 0 AND intent_score <= 1),
  intent_score_band       text NOT NULL
                            CHECK (intent_score_band IN ('none','low','moderate','strong','high')),

  -- Journey (from SOCIAL-1D)
  journey_phase           text,

  -- SOCIAL-1E policy gate (authoritative — preserved for audit)
  policy_decision         text NOT NULL
                            CHECK (policy_decision IN ('ALLOW','REVIEW','BLOCK')),
  policy_reasons          text[] NOT NULL DEFAULT '{}',
  policy_evaluated_at     timestamptz NOT NULL,

  -- NBA recommendation
  action_type             text NOT NULL
                            CHECK (action_type IN (
                              'follow_up', 'personalized_offer', 'cross_sell',
                              'upsell', 'referral_invitation', 'booking_follow_up',
                              'human_handoff', 'do_nothing')),
  recommendation_status   text NOT NULL
                            CHECK (recommendation_status IN (
                              'recommended', 'review_required', 'blocked', 'do_nothing')),
  human_approval_required boolean NOT NULL DEFAULT true,
  reason_codes            text[] NOT NULL DEFAULT '{}',
  evidence_refs           text[] NOT NULL DEFAULT '{}',
  confidence              text NOT NULL CHECK (confidence IN ('low','medium','high')),

  -- Idempotency
  idempotency_key         text NOT NULL,

  -- Lifecycle (append/audit-safe; rows are never hard-deleted)
  -- lifecycle_status: active | superseded | expired | cancelled
  lifecycle_status        text NOT NULL DEFAULT 'active'
                            CHECK (lifecycle_status IN ('active','superseded','expired','cancelled')),

  -- Timestamps
  recommended_at          timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now()
);

-- ── Indexes ───────────────────────────────────────────────────────────────────

-- Primary lookup: workspace + identity
CREATE INDEX IF NOT EXISTS idx_social_nba_workspace_identity
  ON public.social_nba_recommendations (workspace_id, resolved_identity_key);

-- Idempotency lookup
CREATE INDEX IF NOT EXISTS idx_social_nba_idempotency
  ON public.social_nba_recommendations (workspace_id, idempotency_key);

-- Lifecycle filter (finding active rows)
CREATE INDEX IF NOT EXISTS idx_social_nba_lifecycle
  ON public.social_nba_recommendations (workspace_id, lifecycle_status);

-- ── Idempotency Constraint ────────────────────────────────────────────────────
-- Only one ACTIVE recommendation per workspace + idempotency_key.
-- Superseded / expired / cancelled rows are excluded, allowing a new active
-- recommendation to be created after the window closes.

CREATE UNIQUE INDEX IF NOT EXISTS uniq_social_nba_active_idempotency
  ON public.social_nba_recommendations (workspace_id, idempotency_key)
  WHERE lifecycle_status = 'active';

-- ── Row Level Security ────────────────────────────────────────────────────────

ALTER TABLE public.social_nba_recommendations ENABLE ROW LEVEL SECURITY;

-- Service-role bypass (edge functions run as service role)
CREATE POLICY "social_nba_service_role_all"
  ON public.social_nba_recommendations
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- Authenticated users may read their own workspace recommendations only
CREATE POLICY "social_nba_workspace_read"
  ON public.social_nba_recommendations
  FOR SELECT
  TO authenticated
  USING (
    workspace_id = (
      SELECT raw_user_meta_data->>'workspace_id'
      FROM auth.users
      WHERE id = auth.uid()
    )
  );

-- ── Comments ──────────────────────────────────────────────────────────────────

COMMENT ON TABLE public.social_nba_recommendations IS
  'SOCIAL-1F: Controlled Social NBA recommendations. '
  'Append-only audit log. Rows are never hard-deleted. '
  'Execution is NOT triggered by this table — it is a recommendation record only.';

COMMENT ON COLUMN public.social_nba_recommendations.idempotency_key IS
  'Derived from workspace_id + resolved_identity_key + sorted evidence refs + UTC date. '
  'Prevents duplicate active recommendations for the same social event window.';

COMMENT ON COLUMN public.social_nba_recommendations.policy_decision IS
  'Authoritative SOCIAL-1E policy decision preserved for downstream execution proof.';

COMMENT ON COLUMN public.social_nba_recommendations.human_approval_required IS
  'True for all review_required and blocked statuses. '
  'Also true for human_handoff, unverified capability, and risky commercial actions. '
  'MUST be checked by any downstream execution layer before acting.';
